bugs.fix:
Option A (recommended): Add a beforeAll warm-up hook:

test.beforeAll(async ({ browser }) => {
  const page = await browser.newPage();
  await page.goto(PLP_PATH, { waitUntil: 'domcontentloaded', timeout: 60_000 });
  await awaitHydrated(page, { timeout: 30_000 });
  await page.close();
});

Option B: Increase timeout in gotoPlp:
async function gotoPlp(page: Page): Promise<void> {
  await page.goto(PLP_PATH, { waitUntil: 'domcontentloaded' });
  await dismissOverlays(page);
  await awaitHydrated(page, { timeout: 30_000 });
}
